(* [comment removed for export] *)
Definition strL (M : word -> option byte) (c q n : Z) : Prop :=
  L5.defined M ot 24 /\ L5.u8_at RSEGS M ot ((c + 1) mod 256) /\ L5.u64_at RSEGS M ot (c + 1) /\ L5.u64_at RSEGS M (ot + 8) n /\ L5.u64_at RSEGS M (ot + 16) q
  /\ L5.defined M q c /\ 46 <= c <= 2 ^ 27 /\ c mod 2 = 0 /\ 4096 <= q /\ q + c <= hl_ceil L.
Lemma strL_agree M M1 c q n : strL M c q n -> mem_grows M M1 -> L5C.agree_on M M1 ot 24 -> strL M1 c q n.
