Definition ctx (M : word -> option byte) (model1 : Model) (cr1 : credit) (c q : Z) : Prop :=
  mem_ok M /\ saved M /\ thisc M /\ model_but_vm model0 model1 /\ hi_heap HI (((q, c) :: OWN0) ++ LB) cr1 M (m_vmmaps model1) /\ XPost c q cr1.
(* [comment removed for export] *)
Definition tcells (M : word -> option byte) (b rb : Z) : Prop :=
  L5.u8_at RSEGS M (S - 184) 0 /\ L5.u8_at RSEGS M (S - 152) rb /\ L5.u8_at RSEGS M (S - 120) b /\ 0 <= b < 256 /\ VX M b
  /\ 0 <= rb < 256 /\ Z.testbit rb 0 = false.

(* [comment removed for export] *)
Definition fin_stmt : Prop :=
  forall (fx1 : FPState) (R1 : bvmap 5 word) (M1 : word -> option byte) (model1 : Model) (cr1 : credit) (c q n b rb : Z),
    lregs R1 -> strL M1 c q n -> strC M1 q n -> 1 <= n <= 31 -> ctx M1 model1 cr1 c q -> tcells M1 b rb ->
    srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx1 R1 0x46df8 M1 model1) K.
(* [comment removed for export] *)
Lemma carry M M1 (P : Z -> Prop) model1 cr1 c q b rb :
  ctx M model1 cr1 c q -> tcells M b rb -> mem_grows M M1 ->
  (forall a, 0 <= a < 2 ^ 64 -> ~ P a -> M1 (Z_to_bv 64 a) = M (Z_to_bv 64 a)) ->
