Lemma loopA (k : nat) : forall (fx1 : FPState) (R1 : bvmap 5 word) (M1 : word -> option byte) (model1 : Model) (cr1 : credit) (c q n b rb j rr : Z),
  18 - j <= Z.of_nat k ->
  lregs R1 -> getr R1 (reg 10) = Z_to_bv 64 j -> getr R1 (reg 22) = Z_to_bv 64 rr -> getr R1 (reg 23) = Z_to_bv 64 0 -> getr R1 (reg 24) = Z_to_bv 64 0 ->
  0 <= j <= 18 -> 0 <= rr < 10 ^ (29 - n) -> rr < 2 ^ 64 -> 0 <= n <= 28 ->
  strL M1 c q n -> strC M1 q n -> ctx M1 model1 cr1 c q -> tcells M1 b rb ->
