  PM.vstr_at RSEGS PMSP.T3 M' ot x' -> 1 <= PM.vs_size x' <= 31 -> PQTSS.ts_text M' ot x' -> PQTST.ws_post L LB M' 2 x x' ->
  L5C.hpres L LB S PQTSS.WRS_SCR [(ot, 24)] M0 M' ->
  model_but_vm model0 model' -> hi_heap HI (PM.vs_own x' ++ LB) (PQTST.tcredit L x 2 cr0) M' (m_vmmaps model') ->
  srealizes RSEGS SCFG (PMSP.cfg RSEGS R' r M' model') K.

