(* [comment removed for export] *)
Definition XPost (c q : Z) (cr1 : credit) : Prop :=
  match x with
  | PM.VShort _ => c = 48 /\ cr1 = debit L cr0 48 /\ block_range L q 48 /\ blocks_apart q 48 LB
  | PM.VLong c0 _ p0 => if (c0 <=? 44) then c = 48 /\ cr1 = debit L cr0 48 /\ block_range L q 48 /\ blocks_apart q 48 LB else c = c0 /\ q = p0 /\ cr1 = cr0
  end.
Let OWN0 : list (Z * Z) := [].
Let VX : (word -> option byte) -> Z -> Prop := fun _ b => Z.testbit b 0 = false.
